using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class JsonPlaceholderTools(HttpClient httpClient, ILogger<JsonPlaceholderTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Fetch a post by its numeric ID from the JSONPlaceholder API.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var json = await httpClient.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts to this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        logger.LogInformation("Listing posts: {Url}", url);
        var json = await httpClient.GetStringAsync(url, cancellationToken);

        // Return a summary to keep token usage reasonable
        using var doc = JsonDocument.Parse(json);
        var posts = doc.RootElement.EnumerateArray()
            .Select(p => new { id = p.GetProperty("id").GetInt32(), title = p.GetProperty("title").GetString() });
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("Create a new post (simulated — JSONPlaceholder returns the created object but doesn't persist it).")]
    public async Task<string> CreatePost(
        [Description("The user ID authoring the post")] int userId,
        [Description("The post title")] string title,
        [Description("The post body text")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var payload = new { userId, title, body };
        var response = await httpClient.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

